((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2026-9-11","year":2026,"grades":[9,10,11],"label":"9–11 классы","tasksUrl":"assets/kenguru/kenguru_2026_class_9-11.pdf","answersUrl":"assets/kenguru/kenguru_2026_answers.pdf","solutionUrl":"assets/kenguru/kenguru_2026_solution.pdf","answerLetters":"АБВГД","cards":[{"number":1,"title":"Наименьшее значение","question":"Какое из этих числовых выражений имеет наименьшее значение?","options":[{"text":"202 : 6"},{"text":"202,6"},{"text":"20 + 26"},{"text":"202 − 6"},{"text":"20 × 26"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Уберём большие значения","text":"20 + 26 = 46. Числа 202,6, 202 − 6 = 196 и 20 · 26 = 520 больше 46."},{"title":"Сравним частное с 46","text":"202 : 6 меньше 46, потому что 6 · 46 = 276 > 202. Поэтому частное оказывается наименьшим."}],"keyNote":null},{"number":2,"title":"Дата-палиндром","question":"Вася заметил, что несколько лет назад день его рождения пришёлся на дату, запись которой в формате DDMMYYYY является палиндромом (палиндром — число, читающееся одинаково в обе стороны). В каком месяце родился Вася?","options":[{"text":"Январь"},{"text":"Февраль"},{"text":"Сентябрь"},{"text":"Октябрь"},{"text":"Ноябрь"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Запишем дату в обе стороны","text":"У палиндрома первые две цифры года дают номер месяца в обратном порядке. Для года 19… получился бы месяц 91, для 20… — месяц 02."},{"title":"Прочитаем номер месяца","text":"Вася не мог родиться в 19… году. Номер 02 означает февраль."}],"keyNote":null},{"number":3,"title":"Сливы за ужином","question":"В вазе было 19 слив. За ужином каждый из пяти членов семьи съел либо 3, либо 4 сливы. После этого слив не осталось. Сколько человек съели по 4 сливы?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Предположим, что все съели по четыре","text":"Пять человек по четыре сливы съели бы 20 слив. В действительности слив было 19."},{"title":"Учтём одну недостающую сливу","text":"Каждый, кто съел три сливы вместо четырёх, уменьшает итог ровно на одну. Так сделал один человек, а остальные четверо съели по четыре."}],"keyNote":null},{"number":4,"title":"Цифры года","question":"Число 2026 обладает следующими двумя свойствами: в его записи есть ровно две одинаковые цифры и сумма всех его цифр равна 10. Сколько чисел, соответствующих годам XXI века, обладают этими двумя свойствами?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Ограничим последние цифры","text":"Годы XXI века от 2001 до 2099 имеют вид 20xy. У числа 2100 сумма цифр 3. Для остальных годов сумма 10 означает x + y = 8."},{"title":"Проверим совпадения","text":"Из пар с суммой 8 одна цифра может повторить 0 или 2, либо две последние цифры совпадут и будут обе равны 4."},{"title":"Перечислим годы","text":"Получаем 2008, 2026, 2044, 2062 и 2080. Подходит пять годов."}],"keyNote":null},{"number":5,"title":"Четырёхугольник PLMS","question":"Саша нарисовал равносторонний треугольник PQR. Точка S — середина основания PR. Точка M — середина высоты QS, точка L лежит на стороне PQ. LM параллельна PR. Какую часть площади треугольника PQR составляет площадь четырёхугольника PLMS?","options":[{"text":"1/8"},{"text":"3/10"},{"text":"1/4"},{"text":"3/8"},{"text":"1/3"}],"condition":{"src":"assets/grades-9-11/2026/task-05.svg","width":256,"height":266,"alt":"Треугольник PQR с высотой QS и закрашенным четырёхугольником PLMS"},"answer":3,"points":3,"review":[{"title":"Продлим отрезок до правой стороны","text":"Пусть N — пересечение продолжения LM со стороной QR. Высота QМ вдвое меньше QS, поэтому треугольник LQN подобен PQR с коэффициентом 1/2.","image":"assets/grades-9-11/2026/solution-05-1.svg","imageWidth":259,"imageHeight":269},{"title":"Сравним площади","text":"Верхний треугольник занимает (1/2)² = 1/4 всей площади. Оставшаяся трапеция занимает 3/4. Высота QS делит её на равные части, поэтому PLMS занимает 3/8 треугольника."}],"keyNote":null},{"number":6,"title":"Кратность шести","question":"Арина написала семизначное число «193391A». Это число кратно 6. Какая цифра обозначена буквой A?","options":[{"text":"0"},{"text":"2"},{"text":"4"},{"text":"6"},{"text":"8"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Проверим делимость на два","text":"Кратное шести число чётное. Значит, подходящие цифры A — 0, 2, 4, 6 и 8."},{"title":"Проверим делимость на три","text":"Сумма цифр равна 26 + A. Из выбранных цифр только 4 даёт сумму, кратную трём: 26 + 4 = 30."}],"keyNote":null},{"number":7,"title":"Разности соседних чисел","question":"Чему равно значение выражения (1 − 2) − (3 − 4) − (5 − 6) − … − (2025 − 2026)?","options":[{"text":"−1013"},{"text":"−1011"},{"text":"1011"},{"text":"1013"},{"text":"2024"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Посчитаем пары","text":"Каждая скобка равна −1. От 1 до 2026 всего 2026 : 2 = 1013 пар соседних чисел."},{"title":"Учтём минусы","text":"Первая скобка даёт −1, а каждая оставшаяся прибавляет 1, потому что перед ней стоит минус. Результат −1 + 1012 = 1011."}],"keyNote":null},{"number":8,"title":"Числа в клетках","question":"Кристина хочет вписать числа 1, 2, 3, 4, 5, 6, 7 в клетки так, чтобы сумма каждых двух соседних чисел была нечётной, и чтобы сумма чисел в любых трёх последовательных клетках не была кратна 3. Она уже вписала два числа, как показано на рисунке. Какова сумма чисел, которые она напишет в закрашенных клетках?","options":[{"text":"5"},{"text":"7"},{"text":"9"},{"text":"11"},{"text":"13"}],"condition":{"src":"assets/grades-9-11/2026/task-08.svg","width":247,"height":45,"alt":"Ряд из семи клеток. Во второй клетке число 2, в седьмой 5. Закрашены четвёртая и пятая клетки."},"answer":1,"points":3,"review":[{"title":"Расположим чётные числа","text":"Числа должны чередоваться по чётности. Во второй клетке стоит 2, поэтому в четвёртой и шестой клетках расположены 4 и 6 в каком-то порядке."},{"title":"Исключим число 4 в шестой клетке","text":"Если в шестой клетке стоит 4, пятая не может содержать 3. Иначе сумма трёх последних чисел была бы 3 + 4 + 5 = 12. Число 3 оказалось бы рядом с 2, с другой стороны от которого стояло бы 1 или 7. Обе такие тройки дают сумму, кратную трём."},{"title":"Заполним выделенные клетки","text":"Значит, в шестой стоит 6, а в четвёртой — 4. Для пятой подходит только 3, поскольку 1 + 6 + 5 и 7 + 6 + 5 кратны трём. Ряд 1, 2, 7, 4, 3, 6, 5 удовлетворяет правилам. Искомая сумма 4 + 3 = 7."}],"keyNote":null},{"number":9,"title":"Периметр из трёх дуг","question":"На рисунке изображён равносторонний треугольник и три дуги, каждая из которых имеет центр в соответствующей вершине треугольника и радиус, равный длине стороны треугольника. Длина стороны треугольника равна 2 см. Чему равен периметр закрашенной фигуры?","options":[{"text":"π см"},{"text":"6 см"},{"text":"2π см"},{"text":"8 см"},{"text":"4π см"}],"condition":{"src":"assets/grades-9-11/2026/task-09.svg","width":232,"height":204,"alt":"Граница закрашенной фигуры состоит из трёх дуг, соединяющих вершины равностороннего треугольника."},"answer":2,"points":3,"review":[{"title":"Найдём угол дуги","text":"Радиус каждой дуги равен 2 см. Из центра дуги видны две другие вершины равностороннего треугольника под углом 60°."},{"title":"Сложим длины трёх дуг","text":"Каждая дуга занимает 1/6 окружности длины 4π см. Длина трёх дуг составляет 3 · 4π/6 = 2π см."}],"keyNote":null},{"number":10,"title":"Животные на ферме","question":"На ферме живут собаки, овцы, козы, свиньи и куры. Кур больше, чем свиней, свиней больше, чем коз, коз больше, чем овец, и овец больше, чем собак. Собак вдвое меньше, чем кур. Какое минимальное возможное количество животных может жить на ферме?","options":[{"text":"25"},{"text":"30"},{"text":"35"},{"text":"36"},{"text":"40"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Ограничим число собак","text":"Пусть собак n, тогда кур 2n. От количества собак до количества кур четыре строгих увеличения, по меньшей мере на единицу. Значит, 2n ≥ n + 4 и n ≥ 4."},{"title":"Возьмём наименьшие количества","text":"При четырёх собаках получаем 4, 5, 6, 7 и 8 животных каждого вида по порядку. Все условия выполнены, а общая сумма равна 30."}],"keyNote":null},{"number":11,"title":"Грибы пятерых ребят","question":"Пять ребят ходили в лес за грибами. Известно, что один из них нашёл 7 грибов, второй 9, третий 10, четвёртый 13 и пятый 14 грибов. Общее количество грибов у Антона и Лиды в три раза больше, чем у Кати. Общее количество грибов у Миши и Лиды в два раза больше, чем у Пети. Сколько грибов нашла Лида?","options":[{"text":"7"},{"text":"9"},{"text":"10"},{"text":"13"},{"text":"14"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Определим число грибов Кати","text":"Антон и Лида вместе собрали не более 13 + 14 = 27. У Кати не более 9 грибов, то есть 7 или 9. Для 7 двум другим понадобился бы в сумме 21 гриб, но подходящей пары нет."},{"title":"Найдём число грибов Лиды","text":"У Кати 9, а у Антона и Лиды 13 и 14. У Пети 7 или 10. Если 7, у Миши и Лиды вместе 14, хотя одна Лида собрала минимум 13 и у Миши минимум 7. Значит, у Пети 10, а Миша и Лида собрали вместе 20. Это 7 и 13, причём Лиде принадлежат 13 грибов."}],"keyNote":null},{"number":12,"title":"Кольцо из ячеек","question":"Ира хочет вписать простые числа 2, 3, 5, 7, 11, 13 в белые шестиугольные ячейки. Число 2 находится на фиксированном месте. Ира хочет, чтобы сумма чисел в любых двух соседних белых ячейках не равнялась простому числу. Сколькими способами она может заполнить ячейки, следуя этому правилу?","options":[{"text":"2"},{"text":"6"},{"text":"12"},{"text":"60"},{"text":"120"}],"condition":{"src":"assets/grades-9-11/2026/task-12.svg","width":147,"height":153,"alt":"Шесть белых шестиугольников вокруг черного. В нижней ячейке стоит число 2."},"answer":2,"points":4,"review":[{"title":"Выберем соседей числа 2","text":"Суммы 2 + 3, 2 + 5 и 2 + 11 простые. Поэтому по обе стороны от 2 должны стоять 7 и 13. Их можно расположить двумя способами."},{"title":"Заполним оставшиеся ячейки","text":"Другие соседние числа нечётны и дают чётную сумму больше двух. Оставшиеся три числа можно разместить 3 · 2 · 1 = 6 способами. Всего 2 · 6 = 12."}],"keyNote":null},{"number":13,"title":"Точки на окружности","question":"15 точек расположены на окружности и делят её на равные дуги. Сколько всего можно построить правильных многоугольников с вершинами в этих точках?","options":[{"text":"5"},{"text":"7"},{"text":"9"},{"text":"11"},{"text":"13"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Определим число вершин","text":"Соседние вершины правильного многоугольника отстоят на одно и то же число делений окружности. Число вершин делит 15 и не меньше трёх, значит, это 3, 5 или 15."},{"title":"Посчитаем повороты","text":"Треугольников 15 : 3 = 5, пятиугольников 15 : 5 = 3, а пятнадцатиугольник один. Всего 9."}],"keyNote":null},{"number":14,"title":"Ходы жуков-древоточцев","question":"Шесть жуков-древоточцев поселились в старом деревянном кубе, составленном из одинаковых маленьких кубиков. Каждый жук проделал сквозной ход параллельно одному из рёбер куба. На рисунке показано, где начинаются эти шесть ходов. В каком количестве маленьких кубиков не проделан ход?","options":[{"text":"9"},{"text":"10"},{"text":"12"},{"text":"15"},{"text":"21"}],"condition":{"src":"assets/grades-9-11/2026/task-14.svg","width":196,"height":223,"alt":"Большой куб из 27 кубиков с шестью отверстиями, по два на каждой из видимых граней."},"answer":2,"points":4,"review":[{"title":"Сложим длины ходов","text":"Каждый из шести прямых ходов проходит через три маленьких кубика. Сумма 6 · 3 = 18 считает кубики вместе с повторениями."},{"title":"Уберём повторы","text":"Через центральный кубик проходят три хода, через дальний нижний угловой — два. Поэтому различных кубиков с ходами 18 − 2 − 1 = 15. Без ходов осталось 27 − 15 = 12."}],"keyNote":null},{"number":15,"title":"Пирамида из чисел","question":"Алла хочет написать в каждой ячейке число −1 или 1. В трёх верхних рядах число в каждой ячейке должно быть равно произведению двух чисел, расположенных непосредственно под ней. В верхней ячейке Алла уже написала −1, как показано на рисунке. Сколько существует различных способов заполнить остальные ячейки по указанному выше правилу?","options":[{"text":"4"},{"text":"8"},{"text":"10"},{"text":"12"},{"text":"15"}],"condition":{"src":"assets/grades-9-11/2026/task-15.svg","width":254,"height":134,"alt":"Пирамида из четырёх рядов ячеек. В рядах сверху вниз одна, две, три и четыре ячейки. На вершине записано −1."},"answer":1,"points":4,"review":[{"title":"Восстановим один ряд по другому","text":"Зная ряд сверху, можно свободно выбрать первый знак ряда под ним. Каждая следующая ячейка получится из предыдущей и заданного произведения над ней."},{"title":"Посчитаем выборы","text":"У первых клеток второго, третьего и четвёртого рядов по два варианта, ±1. Вместе получается 2 · 2 · 2 = 8 способов."}],"keyNote":null},{"number":16,"title":"Десять равных углов","question":"На рисунке изображена фигура с десятью равными углами, отмеченными серым цветом. Какова градусная мера одного такого угла?","options":[{"text":"96°"},{"text":"105°"},{"text":"108°"},{"text":"115°"},{"text":"120°"}],"condition":{"src":"assets/grades-9-11/2026/task-16.svg","width":294,"height":212,"alt":"Замкнутая ломаная с одним самопересечением и десятью отмеченными углами."},"answer":2,"points":4,"review":[{"title":"Обозначим два угла","text":"Пусть α — каждый из десяти равных углов, а d — внутренний угол в точке самопересечения. В малом четырёхугольнике 3α + d = 360°.","image":"assets/grades-9-11/2026/solution-16-1.svg","imageWidth":93,"imageHeight":109},{"title":"Рассмотрим большой восьмиугольник","text":"Восьмиугольник имеет семь углов α и один вогнутый угол 360° − d. Их сумма равна 6 · 180° = 1080°.","image":"assets/grades-9-11/2026/solution-16-2.svg","imageWidth":293,"imageHeight":213},{"title":"Исключим вспомогательный угол","text":"Сложим 3α + d = 360° и 7α + 360° − d = 1080°. Получаем 10α = 1080°, откуда α = 108°."}],"keyNote":null},{"number":17,"title":"Кто солгал о забеге","question":"Артём, Боря, Кирилл, Данил и Лёша приняли участие в забеге. Один из них не финишировал, а остальные закончили в разное время. Когда позже их спросили о забеге, они ответили:\nАртём: «Я был первым»;\nДанил: «Я был четвёртым»;\nБоря: «Я добежал до финиша и не был четвёртым»;\nКирилл: «Я был вторым или третьим»;\nЛёша: «Я не добежал до финиша».\nИзвестно, что один из мальчиков солгал, а все остальные сказали правду. Кто из мальчиков солгал?","options":[{"text":"Артём"},{"text":"Боря"},{"text":"Кирилл"},{"text":"Данил"},{"text":"Лёша"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Определим, кто не добежал","text":"Если бы Лёша солгал, остальные сказали бы правду и все пятеро финишировали бы. Поэтому Лёша сказал правду, а остальные четверо добежали."},{"title":"Проверим возможную ложь","text":"Кирилл при лжи был бы первым или четвёртым, но эти места тогда уже заняты по правдивым словам Артёма и Данила. Если лжёт Боря, он четвёртый, что противоречит словам Данила. Если лжёт Данил, никто не был бы четвёртым."},{"title":"Проверим оставшийся случай","text":"Солгал Артём. Возможный порядок: Боря, Кирилл, Артём, Данил. Высказывания Бори, Кирилла и Данила верны, а Артём не первый."}],"keyNote":null},{"number":18,"title":"Вода в бутылке","question":"На рисунке показано, как изменяется высота воды в бутылке, когда её переворачивают вверх дном. Объём бутылки составляет 4,5 литра. В не перевёрнутой бутылке вся заполненная водой часть имеет цилиндрическую форму. Какой объём воды находится в бутылке?","options":[{"text":"2,4 л"},{"text":"2,5 л"},{"text":"2,7 л"},{"text":"3 л"},{"text":"3,5 л"}],"condition":{"src":"assets/grades-9-11/2026/task-18.svg","width":387,"height":202,"alt":"Прямая и перевёрнутая бутылка высотой 42 см. В первой вода достигает 24 см, во второй — 30 см."},"answer":3,"points":4,"review":[{"title":"Сравним две цилиндрические части","text":"В прямой бутылке цилиндрическая часть с водой имеет высоту 24 см. В перевёрнутой бутылке цилиндрическая пустая часть имеет высоту 42 − 30 = 12 см."},{"title":"Перейдём от высот к объёмам","text":"Основания цилиндров одинаковы. Воды получается вдвое больше, чем воздуха, поэтому она занимает 2/3 бутылки. Объём 4,5 · 2/3 = 3 литра."}],"keyNote":null},{"number":19,"title":"Треугольник в прямоугольнике","question":"ABCD и DCEF — равные прямоугольники, а O — точка пересечения диагоналей прямоугольника DCEF. Какую часть площади прямоугольника ABEF составляет площадь треугольника ACO?","options":[{"text":"1/4"},{"text":"1/2"},{"text":"1/3"},{"text":"1/5"},{"text":"2/9"}],"condition":{"src":"assets/grades-9-11/2026/task-19.svg","width":221,"height":230,"alt":"Два прямоугольника с общей стороной CD. O — центр правого прямоугольника. Закрашен треугольник ACO."},"answer":0,"points":4,"review":[{"title":"Сравним треугольники на основании AC","text":"O лежит на диагонали DE. Поскольку прямоугольники равны, диагональ DE параллельна AC. Точки O и D равноудалены от прямой AC, поэтому площади ACO и ACD равны."},{"title":"Найдём долю площади","text":"Треугольник ACD занимает половину левого прямоугольника. Сам левый прямоугольник занимает половину ABEF. Получаем 1/2 · 1/2 = 1/4."}],"keyNote":null},{"number":20,"title":"Числа на трёх прямых","question":"Яна хочет разместить числа от 1 до 10 в ячейках, показанных на рисунке. Она хочет, чтобы суммы чисел, размещённых в ячейках на каждой из трёх прямых, были одинаковы. Она также хочет, чтобы эта сумма была как можно больше. Какова будет сумма чисел, которые Яна напишет в трёх закрашенных ячейках?","options":[{"text":"13"},{"text":"18"},{"text":"23"},{"text":"26"},{"text":"27"}],"condition":{"src":"assets/grades-9-11/2026/task-20.svg","width":209,"height":255,"alt":"Три пересекающиеся прямые и десять ячеек. Закрашены три ячейки в местах попарного пересечения прямых."},"answer":3,"points":4,"review":[{"title":"Сложим три одинаковые суммы","text":"Пусть сумма на каждой прямой равна S. Незакрашенные числа встречаются один раз, а три закрашенных — дважды. Значит, 3S = 55 + сумма трёх закрашенных чисел.","image":"assets/grades-9-11/2026/solution-20-1.svg","imageWidth":212,"imageHeight":258},{"title":"Найдём наибольшую возможную сумму","text":"Самая большая тройка 10 + 9 + 8 = 27 даёт 55 + 27 = 82, что не делится на 3. Следующая возможная сумма 26 даёт 81 и S = 27."},{"title":"Проверим расположение","text":"На рисунке показано заполнение с закрашенными 10, 7 и 9. Сумма на каждой прямой равна 27. Искомая сумма трёх закрашенных чисел равна 26.","image":"assets/grades-9-11/2026/solution-20-2.svg","imageWidth":212,"imageHeight":255}],"keyNote":null},{"number":21,"title":"Шахматный турнир","question":"В первом раунде шахматного турнира каждый участник играет по одной партии с каждым другим участником. В случае победы игрок получает 3 очка. В случае ничьей оба игрока получают по 1 очку. А в случае поражения у игрока вычитают 1 очко. В конце первого раунда сумма очков всех игроков равна 90. Сколько игроков участвует в турнире?","options":[{"text":"5"},{"text":"8"},{"text":"10"},{"text":"12"},{"text":"15"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Посчитаем общий вклад партии","text":"При победе и поражении сумма изменений равна 3 − 1 = 2. При ничьей игроки тоже получают в сумме 2 очка. Значит, сыграли 90 : 2 = 45 партий."},{"title":"Посчитаем пары игроков","text":"Среди n игроков есть n(n − 1)/2 пар, каждая сыграла один раз. Равенство n(n − 1) = 90 выполняется при n = 10."}],"keyNote":null},{"number":22,"title":"Окружности и многоугольник","question":"Радиус большой окружности равен 10 см. Внутри неё размещены девять маленьких окружностей, каждая из которых касается большой окружности и двух других маленьких окружностей. Сумма девяти расстояний от центра каждой меньшей окружности до центра большой окружности равна d. Как выражается периметр закрашенного многоугольника через d?","options":[{"text":"90 − 2d"},{"text":"90 − d"},{"text":"180 − d"},{"text":"180 − 2d"},{"text":"180 + 2d"}],"condition":{"src":"assets/grades-9-11/2026/task-22.svg","width":304,"height":302,"alt":"Девять взаимно касающихся соседних окружностей в большой окружности. Их центры соединены сторонами закрашенного многоугольника."},"answer":3,"points":5,"review":[{"title":"Свяжем два вида расстояний","text":"Радиус каждой малой окружности вместе с расстоянием от её центра до большого центра составляет 10 см. Сумма девяти малых радиусов поэтому равна 90 − d."},{"title":"Сложим стороны многоугольника","text":"Две соседние малые окружности касаются друг друга, поэтому длина стороны между их центрами равна сумме их радиусов. Каждый радиус учитывается на двух сторонах. Периметр равен 2(90 − d) = 180 − 2d.","image":"assets/grades-9-11/2026/solution-22-1.svg","imageWidth":306,"imageHeight":306}],"keyNote":null},{"number":23,"title":"Уравнение со степенью","question":"Для двух неотрицательных целых чисел a и b выполняется равенство aᵇ − ab = 2026. Чему равно значение (a + b)?","options":[{"text":"10"},{"text":"13"},{"text":"15"},{"text":"1013"},{"text":"1015"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Ограничим делитель a","text":"При b = 0 левая часть не больше 1. При b ≥ 1 выражение aᵇ − ab делится на положительное a. Поскольку 2026 = 2 · 1013, у a остаются варианты 1, 2, 1013 и 2026."},{"title":"Проверим возможные основания","text":"При a = 1 значение не больше 1. При a = 1013 или 2026 и b ≥ 2 левая часть уже при b = 2 больше 2026 и далее растёт. Для b = 1 она равна нулю."},{"title":"Найдём показатель","text":"При a = 2 и b = 11 получаем 2048 − 22 = 2026. Для b ≥ 2 левая часть строго растёт, поэтому показатель единственный. Сумма a + b = 13."}],"keyNote":null},{"number":24,"title":"Суммы цифр","question":"Лёша посчитал количество четырёхзначных чисел с суммой цифр, равной 3. Затем он посчитал количество четырёхзначных чисел с суммой цифр, равной 33. На сколько один результат больше другого?","options":[{"text":"5"},{"text":"10"},{"text":"43"},{"text":"106"},{"text":"315"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Заменим цифры на дополнения до 9","text":"Преобразование каждой цифры x в 9 − x переводит сумму 3 в сумму 36 − 3 = 33. Четырёхзначные числа взаимно соответствуют, кроме случая, когда у числа с суммой 33 первая цифра 9. Тогда обратный переход даёт ведущий ноль."},{"title":"Посчитаем числа, начинающиеся с 9","text":"Оставшиеся три цифры дают сумму 24. Возможны наборы 9,9,6, 9,8,7 и 8,8,8. Чисел соответственно 3, 6 и 1. Разница равна 10."}],"keyNote":null},{"number":25,"title":"Сдвиг шестиугольника","question":"На рисунке изображены два правильных шестиугольника со стороной 60 см. Правый шестиугольник был получен путём горизонтального сдвига левого шестиугольника на длину отрезка AB. В результате этого сдвига образовались три области равной площади. Какова длина отрезка AB?","options":[{"text":"30 см"},{"text":"39 см"},{"text":"40 см"},{"text":"45 см"},{"text":"52 см"}],"condition":{"src":"assets/grades-9-11/2026/task-25.svg","width":236,"height":188,"alt":"Два перекрывающихся шестиугольника. Общая часть закрашена. A и B отмечают левые концы верхних сторон."},"answer":3,"points":5,"review":[{"title":"Разделим области по горизонтали","text":"Горизонтальная прямая через середины шестиугольников разрезает каждую из трёх областей пополам. Верхние части имеют равные площади и одну высоту, поэтому их средние линии имеют равную длину l.","image":"assets/grades-9-11/2026/solution-25-1.svg","imageWidth":308,"imageHeight":209},{"title":"Используем среднюю линию большой трапеции","text":"Две средние линии вместе образуют среднюю линию ACGE. Её основания имеют длины 60 и 120 см, поэтому 2l = (60 + 120) : 2 = 90."},{"title":"Найдём сдвиг","text":"В левом параллелограмме ABFE средняя линия равна стороне AB. Поэтому AB = l = 45 см."}],"keyNote":null},{"number":26,"title":"Восемь палочек","question":"Имеется восемь палочек. Длины всех палочек различны и равны некоторым целым числам. При этом никакие три палочки не могут образовывать треугольник. Какова минимально возможная длина самой длинной палочки?","options":[{"text":"32"},{"text":"33"},{"text":"34"},{"text":"35"},{"text":"36"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Упорядочим длины","text":"Пусть длины возрастают. Чтобы три палочки не образовали треугольник, каждая длина начиная с третьей должна быть не меньше суммы двух предыдущих. Этого также достаточно: любая другая пара более коротких палочек имеет меньшую сумму."},{"title":"Построим минимальную последовательность","text":"Начнём с минимальных различных положительных чисел 1 и 2. Каждый следующий член берём ровно равным сумме двух предыдущих. Получаем 1, 2, 3, 5, 8, 13, 21, 34. Минимальная длина восьмой палочки — 34."}],"keyNote":null},{"number":27,"title":"Квадраты в шестиугольнике","question":"ABCDEF — правильный шестиугольник, ABGH и BCIJ — квадраты, расположенные как показано на рисунке. P — точка пересечения отрезков GH и IJ. Каково отношение площадей треугольников JGP и BGJ?","options":[{"text":"1 : 4"},{"text":"√3 : 6"},{"text":"1 : 3"},{"text":"2 : 5"},{"text":"1 : 2"}],"condition":{"src":"assets/grades-9-11/2026/task-27.svg","width":297,"height":263,"alt":"Шестиугольник ABCDEF, квадраты ABGH и BCIJ, пересечение P и отрезок JG."},"answer":2,"points":5,"review":[{"title":"Выделим равносторонний треугольник","text":"Пусть длина стороны шестиугольника — s. У треугольника BJG стороны BG и BJ длины s и угол между ними 60°, поэтому треугольник равносторонний. Высота из B к GJ равна s√3/2."},{"title":"Найдём высоту треугольника JGP","text":"JG наклонён на 30° к горизонтали, JP — на 60°. Точка J находится на срединной высоте квадрата ABGH, так что JP · sin 60° = s/2 и JP = s/√3. Тогда высота из P к GJ равна JP · sin 30° = s/(2√3)."},{"title":"Сравним высоты","text":"Основание GJ у треугольников общее. Отношение высот [s/(2√3)] : [s√3/2] равно 1 : 3."}],"keyNote":null},{"number":28,"title":"Две хорды","question":"В окружности радиусом 12 см проведены две перпендикулярные хорды, делящие круг на четыре области, как показано на рисунке. Одна хорда находится на расстоянии 3 см от центра, а другая — на расстоянии 4 см от центра. Сумма площадей областей A и C на x см² больше, чем сумма площадей областей B и D. Чему равно значение x?","options":[{"text":"9"},{"text":"16"},{"text":"36"},{"text":"48"},{"text":"60"}],"condition":{"src":"assets/grades-9-11/2026/task-28.svg","width":194,"height":196,"alt":"Области в круге расположены по часовой стрелке от верхней левой: A, B, C, D. Центр находится в C."},"answer":3,"points":5,"review":[{"title":"Отразим хорды через центр","text":"Две отражённые хорды вместе с исходными задают прямоугольник в центре. Остальные части образуют равные пары по центральной симметрии и отражениям."},{"title":"Сравним площади","text":"При вычитании суммы площадей B и D из суммы площадей A и C равные части попарно сокращаются. Остаётся площадь серого прямоугольника.","image":"assets/grades-9-11/2026/solution-28-1.svg","imageWidth":211,"imageHeight":209},{"title":"Найдём размеры прямоугольника","text":"Стороны равны удвоенным расстояниям до хорд: 6 и 8 см. Площадь равна 6 · 8 = 48 см²."}],"keyNote":null},{"number":29,"title":"Ириски из коробки","question":"Андрей и Рома по очереди достают ириски из коробки: Андрей берёт 1 ириску, затем Рома берёт 2, Андрей берёт 3, Рома берёт 4 и так далее. Когда ирисок становится недостаточно, мальчик, чья очередь, забирает все оставшиеся ириски. В конце у Андрея оказывается 407 ирисок. Сколько ирисок было в коробке в начале?","options":[{"text":"814"},{"text":"827"},{"text":"834"},{"text":"841"},{"text":"851"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Посчитаем полные ходы Андрея","text":"Сумма первых n нечётных чисел равна n². Андрей взял 407 ирисок, а 20² = 400 и 21² = 441. Поэтому он сделал двадцать полных ходов и последним взял оставшиеся 7 ирисок."},{"title":"Сложим полные ходы и остаток","text":"До последнего хода мальчики взяли по очереди 1, 2, …, 40 ирисок. В коробке было 40 · 41 : 2 + 7 = 827 ирисок."}],"keyNote":null},{"number":30,"title":"Цифры по кругу","question":"Наташа вписала цифры 1, 2, …, 9 в кружки в произвольном порядке. Затем она выписала 9 трёхзначных чисел, каждое из которых состоит из цифр, стоящих в трёх кружках подряд по часовой стрелке. Например, ▲♦★, ♦★♥ и так далее. Одно из этих чисел (обозначим его a) является делителем суммы других 8 чисел. Сколько существует возможных значений числа a?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":{"src":"assets/grades-9-11/2026/task-30.svg","width":265,"height":265,"alt":"Девять кружков на окружности. В четырёх соседних кружках показаны символы ▲, ♦, ★ и ♥."},"answer":1,"points":5,"review":[{"title":"Найдём общую сумму","text":"Каждая цифра ровно по разу занимает место сотен, десятков и единиц. Сумма всех девяти чисел равна 45 · 111 = 4995. Если a делит сумму остальных, то делит и 4995 = 3³ · 5 · 37."},{"title":"Переберём трёхзначные делители","text":"Если a кратно и 37, и 3, то кратно 111. У любого такого трёхзначного числа все цифры одинаковы, что невозможно. Из чисел с множителем 37 остаётся 185. Без множителя 37 трёхзначный делитель числа 135 только один: 135."},{"title":"Проверим, что оба возможны","text":"У 135 и 185 разные ненулевые цифры. Любую из этих троек можно разместить подряд в круге, а оставшиеся цифры расставить произвольно. Подходящих значений два."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2026-9-11"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2026] ?? []).find(edition => edition.id === "2026-9-11")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
